    public Object parseTrade(Object trade, Object... optionalArgs)
    {
        //
        // fetchTrades (public) v1
        //
        //      {
        //          "id":2278466664,
        //          "side":"SELL",
        //          "price":56810.7,
        //          "size":0.08798,
        //          "exec_date":"2021-11-19T11:46:39.323",
        //          "buy_child_order_acceptance_id":"JRF20211119-114209-236525",
        //          "sell_child_order_acceptance_id":"JRF20211119-114639-236919"
        //      }
        //
        // fetchMyTrades
        //
        //      {
        //          "id": 37233,
        //          "side": "BUY",
        //          "price": 33470,
        //          "size": 0.01,
        //          "exec_date": "2015-07-07T09:57:40.397",
        //          "child_order_id": "JOR20150707-060559-021935",
        //          "child_order_acceptance_id": "JRF20150707-060559-396699"
        //          "commission": 0,
        //      },
        //
        Object market = Helpers.getArg(optionalArgs, 0, null);
        Object side = this.safeStringLower(trade, "side");
        if (Helpers.isTrue(!Helpers.isEqual(side, null)))
        {
            if (Helpers.isTrue(Helpers.isLessThan(((String)side).length(), 1)))
            {
                side = null;
            }
        }
        Object order = null;
        if (Helpers.isTrue(!Helpers.isEqual(side, null)))
        {
            Object idInner = Helpers.add(side, "_child_order_acceptance_id");
            if (Helpers.isTrue(Helpers.inOp(trade, idInner)))
            {
                order = Helpers.GetValue(trade, idInner);
            }
        }
        if (Helpers.isTrue(Helpers.isEqual(order, null)))
        {
            order = this.safeString(trade, "child_order_acceptance_id");
        }
        Object timestamp = this.parse8601(this.safeString(trade, "exec_date"));
        Object priceString = this.safeString(trade, "price");
        Object amountString = this.safeString(trade, "size");
        Object id = this.safeString(trade, "id");
        market = this.safeMarket(null, market);
        final Object finalMarket = market;
        final Object finalOrder = order;
        final Object finalSide = side;
        return this.safeTrade(new java.util.HashMap<String, Object>() {{
            put( "id", id );
            put( "info", trade );
            put( "timestamp", timestamp );
            put( "datetime", Bitflyer.this.iso8601(timestamp) );
            put( "symbol", Helpers.GetValue(finalMarket, "symbol") );
            put( "order", finalOrder );
            put( "type", null );
            put( "side", finalSide );
            put( "takerOrMaker", null );
            put( "price", priceString );
            put( "amount", amountString );
            put( "cost", null );
            put( "fee", null );
        }}, market);
    }

